"use strict";

// ---- PUBLIC TICKET VIEW (?ticket=XXX) - QR quét ra hình phiếu thật, không cần đăng nhập ----
(function(){
  try{
    var _qp = new URLSearchParams(window.location.search);
    var _tk = _qp.get("ticket") || _qp.get("q") || "";
    if(!_tk) return;
    window.__PGH_PUBLIC_TICKET = _tk;
    document.addEventListener("DOMContentLoaded", function(){
      var root = document.getElementById("root");
      if(root) root.style.display = "none";
      var wrap = document.createElement("div");
      wrap.id = "pgh-public-ticket";
      wrap.style.cssText = "max-width:760px;margin:0 auto;padding:16px;font-family:'Be Vietnam Pro',Inter,system-ui,sans-serif;background:#fff;color:#111827;";
      wrap.innerHTML = '<div style="text-align:center;padding:40px 16px;color:#6b7280">Đang tải phiếu '+ _tk +'...</div>';
      document.body.appendChild(wrap);
      function esc(s){ return String(s==null?"":s).replace(/[&<>"]/g, function(c){ return {"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c]; }); }
      function renderTicket(ticket){
        var cust = ticket.customer || ticket.khachHang || {};
        var prods = ticket.products || ticket.sanPham || [];
        var comp = ticket.company || {};
        var rows = prods.map(function(p,i){ return '<tr><td style="padding:8px;border:1px solid #e5e7eb;text-align:center">'+(i+1)+'</td><td style="padding:8px;border:1px solid #e5e7eb">'+esc(p.maKho||p.ma||"")+'</td><td style="padding:8px;border:1px solid #e5e7eb">'+esc(p.tenSP||p.ten||"")+'</td><td style="padding:8px;border:1px solid #e5e7eb;text-align:center">'+esc(p.quyCach||"")+'</td><td style="padding:8px;border:1px solid #e5e7eb;text-align:center">'+esc(p.soGoi||p.soLuong||"")+'</td><td style="padding:8px;border:1px solid #e5e7eb;text-align:center">'+esc(p.soKg||p.kg||"")+'</td></tr>'; }).join("");
        var totalKg = ticket.totalKg || ticket.tongKg || "";
        wrap.innerHTML = '<div style="text-align:center;border-bottom:2px solid #3C2415;padding-bottom:12px;margin-bottom:12px"><div style="font-size:22px;font-weight:800;color:#3C2415">PHIẾU GIAO HÀNG</div><div style="font-size:13px;color:#6b7280">'+esc(comp.tenXuong||"RUNAM")+' '+(comp.sdtXuong?" - "+esc(comp.sdtXuong):"")+'</div></div>'
          + '<div style="display:flex;justify-content:space-between;gap:12px;font-size:13px;margin-bottom:12px"><div><b>Số phiếu:</b> '+esc(ticket.soPhieu||_tk)+'</div><div><b>Ngày giao:</b> '+esc(ticket.ngayGiao||"")+'</div></div>'
          + '<div style="background:#FFFBEB;border:1px solid #F3E8D0;border-radius:10px;padding:12px;margin-bottom:12px;font-size:13px"><b>Khách hàng:</b> '+esc(cust.tenDaiLy||cust.ten||"")+'<br>'+esc(cust.diaChi||"")+'<br>Người nhận: '+esc(cust.nguoiNhan||"")+' - '+esc(cust.sdt||cust.sdtNhan||"")+'</div>'
          + '<table style="width:100%;border-collapse:collapse;font-size:13px"><thead><tr><th style="padding:8px;border:1px solid #e5e7eb;background:#FFFBEB">STT</th><th style="padding:8px;border:1px solid #e5e7eb;background:#FFFBEB">Mã kho</th><th style="padding:8px;border:1px solid #e5e7eb;background:#FFFBEB">Tên SP</th><th style="padding:8px;border:1px solid #e5e7eb;background:#FFFBEB">Quy cách</th><th style="padding:8px;border:1px solid #e5e7eb;background:#FFFBEB">Số gói</th><th style="padding:8px;border:1px solid #e5e7eb;background:#FFFBEB">Số kg</th></tr></thead><tbody>'+rows+'</tbody></table>'
          + '<div style="text-align:right;font-weight:800;margin-top:12px;font-size:14px">Tổng: '+esc(totalKg)+' kg</div>'
          + '<div style="display:flex;justify-content:space-between;margin-top:28px;font-size:13px"><div style="text-align:center">Người giao<br><br>_________________</div><div style="text-align:center">Người nhận<br><br>_________________</div></div>'
          + '<div style="text-align:center;margin-top:24px"><button onclick="window.print()" style="padding:10px 22px;border-radius:999px;background:#3C2415;color:#fff;font-weight:700;border:none">In phiếu</button> <a href="'+window.location.pathname+'" style="display:inline-block;margin-left:8px;padding:10px 18px;border-radius:999px;border:1px solid #e5e7eb;color:#374151;text-decoration:none;font-weight:600">Mở app</a></div>';
      }
      // Try server API first, then local offline storage
      fetch("/api/history?q="+encodeURIComponent(_tk)).then(function(r){ return r.json(); }).then(function(data){
        var list = Array.isArray(data.tickets)?data.tickets:(Array.isArray(data)?data:[]);
        var found = list.find(function(x){ return String(x.soPhieu||"")===String(_tk) || String(x.id||"")===String(_tk); });
        if(found){ renderTicket(found); return; }
        throw new Error("not found");
      }).catch(function(){
        try{
          var uname = "";
          try{ var s = JSON.parse(localStorage.getItem("pgh_offline_identity")||"null"); if(s&&s.username) uname=s.username; }catch(e){}
          // Fallback: try to read from PghOfflineStorage if available
          if(window.PghOfflineStorage && uname){
            window.PghOfflineStorage.listTickets(uname).then(function(entries){
              var f = (entries||[]).find(function(x){ return String((x.ticket&&x.ticket.soPhieu)||x.soPhieu||"")===String(_tk); });
              if(f) renderTicket(f.ticket||f);
              else wrap.innerHTML = '<div style="text-align:center;padding:40px;color:#991b1b">Không tìm thấy phiếu '+esc(_tk)+'. Phiếu có thể đã bị xóa hoặc bạn đang mở trên máy khác.</div>';
            }).catch(function(){ wrap.innerHTML = '<div style="text-align:center;padding:40px;color:#991b1b">Không tải được phiếu. Hãy mở lại khi có mạng.</div>'; });
          } else {
            wrap.innerHTML = '<div style="text-align:center;padding:40px;color:#991b1b">Không tìm thấy phiếu '+esc(_tk)+'. Hãy mở khi có mạng để tải phiếu từ server.</div>';
          }
        }catch(e){ wrap.innerHTML = '<div style="text-align:center;padding:40px;color:#991b1b">Không tải được phiếu.</div>'; }
      });
      // Load Google Fonts for public view
      try{ var lk=document.createElement("link"); lk.rel="stylesheet"; lk.href="'+GOOGLE+'"; document.head.appendChild(lk); }catch(e){}
    });
  }catch(e){}
})();


